        self.assertEqual(loads('a = "\\u0041\\u00e9"\n'), {"a": "A\u00e9"})

    def test_escape_backslash_and_quote(self):
        self.assertEqual(loads('a = "x\\\\y\\"z"\n'), {"a": 'x\\y"z'})

    def test_invalid_escape(self):
        e = error_of('a = "\\q"\n')
        self.assertTrue(e.message.startswith("invalid escape"))
        self.assertEqual(e.lineno, 1)

    def test_short_unicode_escape_is_invalid(self):
        self.assertTrue(error_of('a = "\\u12"\n').message.startswith("invalid escape"))

    def test_backslash_at_end_of_line_is_unterminated(self):
        self.assertTrue(error_of('a = "abc\\\n').message.startswith("unterminated string"))

    def test_single_quotes_are_literal(self):
        self.assertEqual(loads("a = 'x\\\\n\\'\n"), {"a": "x\\\\n\\"})

    def test_quoted_is_never_converted(self):
        self.assertEqual(loads('a = "true"\nb = \'12\'\n'), {"a": "true", "b": "12"})

    def test_text_after_string(self):
        self.assertTrue(error_of('a = "x" y\n').message.startswith("unexpected text after string"))
        self.assertTrue(error_of('a = "x"#c\n').message.startswith("unexpected text after string"))
        self.assertEqual(loads('a = "x"  # ok\n'), {"a": "x"})

    def test_string_must_close_on_its_line(self):
        e = error_of('a = "one\ntwo"\n')
        self.assertTrue(e.message.startswith("unterminated string"))
        self.assertEqual(e.lineno, 1)

    def test_value_error_on_continuation_reports_key_line(self):
        e = error_of("a =\n  \"x\\q\"\n")
        self.assertTrue(e.message.startswith("invalid escape"))
        self.assertEqual(e.lineno, 1)


class ListTest(unittest.TestCase):
    def test_nested_and_empty(self):
        self.assertEqual(loads("a = [[1, 2], [], [\"x\"]]\nb = [ ]\n"),
                         {"a": [[1, 2], [], ["x"]], "b": []})

    def test_bracket_in_token_is_invalid(self):
        self.assertTrue(error_of("a = [x[1]]\n").message.startswith("invalid list"))

    def test_quote_inside_token_is_ordinary(self):
        self.assertEqual(loads("a = [it's]\n"), {"a": ["it's"]})

    def test_token_keeps_inner_spaces_and_hash_without_space(self):
        self.assertEqual(loads("a = [x y, b#c]\n"), {"a": ["x y", "b#c"]})

    def test_comments_and_newlines_between_items(self):
        text = "a = [\n  1, # first\n  2 ; second\n  ,3]\n"
        self.assertEqual(loads(text), {"a": [1, 2, 3]})

    def test_invalid_lists(self):
        for text in ("a = [,]\n", "a = [1,,2]\n", "a = [\"a\" \"b\"]\n", "a = [1]x\n",
                     "a = [[1] [2]]\n", "a = [1 ]]\n"):
            self.assertTrue(error_of(text).message.startswith("invalid list"), text)

    def test_unterminated_list(self):
        for text in ("a = [1, 2\n", "a = [\n", "a = [1,\n  2,\n"):
            e = error_of(text)
            self.assertTrue(e.message.startswith("unterminated list"), text)
            self.assertEqual(e.lineno, 1)

    def test_unterminated_string_inside_list(self):
        self.assertTrue(error_of('a = ["abc]\n').message.startswith("unterminated string"))

    def test_nested_list_items_keep_types(self):
        self.assertEqual(loads("a = [1.5, true, 0x10, \"7\"]\n"), {"a": [1.5, True, 16, "7"]})


class DuplicateTest(unittest.TestCase):
    def test_duplicate_key_in_included_section_reports_key_line(self):
        e = error_of("[a]\nx = 1\n[a.b]\n[a]\n")
        self.assertTrue(e.message.startswith("duplicate section"))
        self.assertEqual(e.lineno, 4)

    def test_key_then_table_conflict(self):
        self.assertTrue(error_of("a = 1\n[a]\n").message.startswith("key conflict"))
        self.assertTrue(error_of("a = 1\n[a.b]\n").message.startswith("key conflict"))
        self.assertTrue(error_of("a = 1\na.b = 2\n").message.startswith("key conflict"))

    def test_table_then_value_conflict(self):
        e = error_of("a.b = 1\na = 2\n")
        self.assertTrue(e.message.startswith("key conflict"))
        self.assertEqual(e.lineno, 2)

    def test_bad_value_wins_over_duplicate(self):
        e = error_of('a = 1\na = "open\n')
        self.assertTrue(e.message.startswith("unterminated string"))
        self.assertEqual(e.lineno, 2)

    def test_duplicate_key_message_names_key(self):
        e = error_of("a.b = 1\na.b = 2\n")
        self.assertTrue(e.message.startswith("duplicate key"))
        self.assertIn("a.b", e.message)


class ErrorObjectTest(unittest.TestCase):
    def test_attributes_and_str(self):
        e = error_of("x = 1\ny\n", base_dir=None)
        self.assertIsInstance(e, ValueError)
        self.assertEqual(e.message, "invalid line")
        self.assertEqual(e.lineno, 2)
        self.assertEqual(e.source, "<string>")
        self.assertEqual(str(e), "<string>:2: invalid line")


class IncludeErrorTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)

    def write(self, name, text):
        path = os.path.join(self.tmp.name, name)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(text)
        return path

    def test_invalid_include_forms(self):
        for text in ("@include\n", "@include base.ini\n", '@include "a.ini\n',
                     '@include "a.ini"x\n', '@include "a.ini"#c\n', "@include \"a\\q\"\n"):
            e = error_of(text, base_dir=self.tmp.name)
            self.assertTrue(e.message.startswith("invalid include"), text)
            self.assertEqual(e.lineno, 1)

    def test_include_comment_with_space_is_fine(self):
        self.write("a.ini", "x = 1\n")
        self.assertEqual(loads('@include "a.ini"   ; note\n', base_dir=self.tmp.name), {"x": 1})

    def test_word_boundary(self):
        self.assertTrue(error_of("@includes \"a\"\n", base_dir=self.tmp.name).message.startswith("invalid line"))
        self.assertTrue(error_of("@foo\n", base_dir=self.tmp.name).message.startswith("invalid line"))

    def test_no_base_dir(self):
        self.assertTrue(error_of('@include "a.ini"\n').message.startswith("include needs a base directory"))

    def test_cannot_read_include(self):
        e = error_of('x = 1\n@include "missing.ini"\n', base_dir=self.tmp.name)
        self.assertTrue(e.message.startswith("cannot read include"))
        self.assertEqual(e.lineno, 2)

    def test_include_continues_section(self):
        self.write("part.ini", "inner = 1\n")
        main = self.write("main.ini", '[s]\nbefore = 1\n@include "part.ini"\nafter = 2\n')
        self.assertEqual(load(main), {"s": {"before": 1, "inner": 1, "after": 2}})

    def test_error_inside_include_uses_its_source(self):
        self.write("sub/bad.ini", "ok = 1\n\nok = 2\n")
        main = self.write("main.ini", '@include "sub/bad.ini"\n')
        e = None
        try:
            load(main)
        except ParseError as exc:
            e = exc
        self.assertIsNotNone(e)
        self.assertEqual(e.source, os.path.normpath(os.path.join(self.tmp.name, "sub/bad.ini")))
        self.assertEqual(e.lineno, 3)
        self.assertTrue(e.message.startswith("duplicate key"))

    def test_same_file_twice_is_not_a_cycle_but_duplicates(self):
        self.write("base.ini", "x = 1\n")
        main = self.write("main.ini", '@include "base.ini"\n@include "base.ini"\n')
        e = None
        try:
            load(main)
        except ParseError as exc:
            e = exc
        self.assertIsNotNone(e)
        self.assertTrue(e.message.startswith("duplicate key"))

    def test_self_include_is_a_cycle(self):
        main = self.write("self.ini", '@include "self.ini"\n')
        with self.assertRaises(ParseError) as ctx:
            load(main)
        self.assertTrue(ctx.exception.message.startswith("include cycle"))
        self.assertEqual(ctx.exception.lineno, 1)

    def test_load_missing_file_raises_oserror(self):
        with self.assertRaises(OSError) as ctx:
            load(os.path.join(self.tmp.name, "nope.ini"))
        self.assertNotIsInstance(ctx.exception, ParseError)

    def test_load_strips_bom(self):
        path = os.path.join(self.tmp.name, "bom.ini")
        with open(path, "w", encoding="utf-8") as handle:
            handle.write("\ufeffa = 1\n")
        self.assertEqual(load(path), {"a": 1})


if __name__ == "__main__":
    unittest.main()

